// ============================================================ VEINTE DESTINOS MÁS (modo Atenas, 386 a.C.)
// Las regiones que faltaban: Dóride, las dos Lócrides, Sicionia, las islas Jónicas, el norte del Egeo, Cos, Eólida y Dóride de Asia,
// Sicilia y la Magna Grecia, Cirene y el Ponto Euxino. Cada destino: estelas a la llegada, un personaje con su lección y vida del pueblo.
const D386B=[
 {id:'doride',pos:[22.42,38.67],links:[['eta','doride'],['doride','parnaso']],
  cfg:{site:[80,-120,22],houses:16,spread:80,temple:{name:'Santuario de Apolo en Citinio',W:9,L:16,nW:4,nL:8,colH:5,colD:0.8}},
  steles:[['doride_patria','La patria de los dorios','ΔΩΡΙΣ','Cuatro aldeas, Erineo, Beo, Citinio y Pindo, forman esta pequeña tierra de pastores. Los dorios del Peloponeso, espartanos, argivos y corintios, dicen que sus antepasados salieron de aquí con los hijos de Heracles para conquistar el sur: es el llamado «retorno de los Heráclidas». Por eso la llaman la metrópolis, la ciudad madre, de los dorios.'],
   ['doride_esparta','Esparta no olvida','ΤΑΝΑΓΡΑ','En el 457, cuando los focidios atacaron la Dóride, Esparta envió mil quinientos hoplitas y diez mil aliados para defender la tierra de sus antepasados. A la vuelta, cerca de Tanagra, en Beocia, se enfrentaron a los atenienses y vencieron. Tucídides lo cuenta en el libro primero.']],
  vida:{kinds:['pine','olive','pine','cypress'],fauna:[['goat',6],['dog',2],['hen',3]],barks:['Aquí somos pocos, pero hasta los reyes de Esparta nos llaman padres.','Mis cabras pasan el verano en el Eta y el invierno en el valle.','¿Dorios? Aquí lo somos todos: el nombre salió de este valle.']},
  npc:{id:'damon_doride',name:'Damón',title:'Pastor de Citinio',glyph:'Δ',look:{chiton:'#8a7a5a',exomis:true,hair:'#3b2a1e',beard:true,staff:true},
   cat:'Historia',lesson:'La Dóride, patria de los dorios',where:'En la Dóride, junto a la llegada',
   summary:'La Dóride, un valle pequeño entre el Eta y el Parnaso con cuatro aldeas (la tetrápolis), era considerada la metrópolis de los dorios. Según la tradición, desde aquí partieron los Heráclidas y los dorios hacia el Peloponeso. Esparta la protegió: en el 457 envió un ejército contra los focidios que la atacaban (Tucídides I 107).',
   intro:'¡Eh, forastero! Cuidado con el perro, que muerde a los que no hablan dorio. Soy Damón. Si vienes del sur, seguro que somos parientes.',
   topics:[['¿Por qué dicen que es la patria de los dorios?','Porque de aquí salieron. Doro, el hijo de Heleno, dio nombre a nuestro pueblo, y en este valle vivieron sus hijos. Luego los descendientes de Heracles bajaron al Peloponeso con los dorios y se repartieron Esparta, Argos y Mesenia. Eso cuentan los viejos, y en Esparta también lo cuentan.'],
    ['¿Y cómo vivís?','Con cabras, ovejas y un poco de cebada. No tenemos murallas grandes ni teatro. Lo que tenemos son amigos poderosos: cuando los focidios quisieron quedarse con nuestras aldeas, en tiempos de mi bisabuelo, Esparta mandó un ejército entero.']],
   quiz:{q:'¿Por qué llamaban a la Dóride «metrópolis de los dorios»?',a:['Porque la tradición decía que de allí habían salido los dorios hacia el Peloponeso','Porque era la ciudad doria más grande','Porque allí vivía el rey de Esparta'],ko:'No: era un valle pequeño de pastores, pero la tradición decía que los dorios habían salido de allí.'}},
  src:{a:['Tucídides I 107','Heródoto I 56 y VIII 31','Estrabón IX 4.10'],m:[],n:['Damón es inventado.']}},

 {id:'anfisa',pos:[22.38,38.53],links:[['delfos','anfisa'],['anfisa','doride']],
  cfg:{site:[100,-90,22],houses:24,spread:90,temple:{name:'Santuario de Atenea',W:10,L:18,nW:6,nL:11}},
  steles:[['anfisa_llanura','La llanura sagrada','ΚΙΡΡΑΙΟΝ ΠΕΔΙΟΝ','A los pies de Anfisa se extiende la llanura de Crisa, que baja hasta el mar. Hace casi dos siglos, tras la primera guerra sagrada, se consagró a Apolo de Delfos: nadie puede ararla ni plantar en ella. La vigila la Anfictionía, el consejo de los pueblos vecinos que cuida el santuario.'],
   ['anfisa_futuro','Lo que vendrá','ΑΙΣΧΙΝΗΣ','En el 339, el ateniense Esquines acusará ante la Anfictionía a los de Anfisa de cultivar la llanura sagrada. Estallará una nueva guerra sagrada, y la Anfictionía llamará a Filipo de Macedonia. Al año siguiente, en Queronea, Filipo vencerá a Atenas y Tebas.']],
  vida:{kinds:['olive','olive','pine','cypress'],fauna:[['goat',3],['dog',2],['hen',4],['pig',2]],barks:['Los olivos llegan hasta la llanura, pero ni uno más allá: aquello es del dios.','Los de Delfos nos miran por encima del hombro. Pero comen nuestro aceite.','Mi abuelo todavía llevaba siempre la espada, como en los tiempos antiguos.']},
  npc:{id:'timon_anfisa',name:'Timón',title:'Olivarero de Anfisa',glyph:'Τ',look:{chiton:'#9a8a6a',exomis:true,hair:'#2a1a12',beard:true},
   cat:'Religión',lesson:'Anfisa y la Anfictionía de Delfos',where:'En Anfisa, en la Lócride Ozolia',
   summary:'Anfisa era la ciudad principal de los locrios ozolios, al oeste de Delfos. La llanura de Crisa, a sus pies, estaba consagrada a Apolo desde la primera guerra sagrada (hacia el 590) y no podía cultivarse. La Anfictionía, consejo de pueblos vecinos, protegía el santuario. En el 339 la acusación de cultivarla desencadenó la cuarta guerra sagrada y la intervención de Filipo II.',
   intro:'Salud. Mira qué olivos: el aceite de Anfisa se vende en Delfos a los peregrinos de toda Grecia. Soy Timón. ¿Vas a consultar al dios o vienes a comprar?',
   topics:[['¿Qué es la Anfictionía?','Un consejo de doce pueblos de alrededor de Delfos: tesalios, beocios, focidios, dorios, jonios, nosotros los locrios… Se reúnen dos veces al año, en primavera y en otoño, y cuidan del santuario y de su dinero. Si alguien toca lo que es del dios, la Anfictionía declara la guerra sagrada.'],
    ['¿Por qué no se puede cultivar la llanura?','Porque es de Apolo. Hace mucho, la ciudad de Crisa cobraba a los peregrinos que subían a Delfos. Los anfictiones la destruyeron y juraron que su tierra no se volvería a arar nunca. Y ahí está, llena de hierba, con lo buena que es.'],
    ['¿Por qué los locrios de aquí llevan armas?','Tucídides, el ateniense, escribió que nosotros, los etolios y los acarnanios seguimos yendo armados por la calle, como hacían todos los griegos antes, cuando había piratas y bandidos. Algo de razón tiene: los caminos de estos montes no son seguros.']],
   quiz:{q:'¿Por qué no se podía cultivar la llanura de Crisa?',a:['Porque estaba consagrada a Apolo de Delfos','Porque era un pantano','Porque pertenecía a Esparta'],ko:'No: tras la primera guerra sagrada, la llanura se consagró a Apolo y quedó prohibido cultivarla.'}},
  src:{a:['Tucídides I 5 y III 101','Esquines, Contra Ctesifonte 107-124','Pausanias X 37-38'],m:[],n:['Timón es inventado.']}},

 {id:'opunte',pos:[22.98,38.66],links:[['termopilas','opunte']],port:[1,0,'Opunte'],
  cfg:{site:[60,-130,20],houses:26,spread:90,temple:{name:'Santuario de Áyax',W:9,L:16,nW:4,nL:8,colH:5,colD:0.8}},
  steles:[['opunte_ayax','La tierra de los dos héroes','ΑΙΑΣ ΚΑΙ ΠΑΤΡΟΚΛΟΣ','De aquí era Áyax, el hijo de Oileo, el «Áyax menor», que mandaba a los locrios en la guerra de Troya. Y aquí nació Patroclo, el amigo de Aquiles: según la Ilíada, de niño mató por accidente a otro muchacho jugando a las tabas, y su padre tuvo que llevárselo a Tesalia, a la casa de Peleo.'],
   ['opunte_doncellas','Las doncellas locrias','ΛΟΚΡΙΔΕΣ ΠΑΡΘΕΝΟΙ','Cuando cayó Troya, Áyax arrancó a Casandra del altar de Atenea. Para pagar aquel sacrilegio, los locrios envían a Ilión, desde hace siglos, a dos muchachas nobles, que sirven en el templo de Atenea. Se cuenta que los troyanos las esperan en la playa para matarlas y que deben entrar a escondidas en el santuario.']],
  vida:{kinds:['olive','pine','plane','olive'],fauna:[['dog',2],['hen',4],['goat',2]],barks:['Desde aquí se ve Eubea: con buen tiempo, cruzar es cosa de medio día.','Este año le toca a la hija del vecino ir a Troya. Su madre no para de llorar.','Patroclo jugaba a las tabas en esta plaza. Eso dicen.']},
  npc:{id:'nicareta_opunte',name:'Nicareta',title:'Madre locria',glyph:'Ν',look:{female:true,chiton:'#e8dfcc',himation:'#4f6a7d',hair:'#3b2a1e'},
   cat:'Religión',lesson:'Los locrios y las doncellas de Troya',where:'En Opunte, en la Lócride oriental',
   summary:'Opunte era la ciudad principal de los locrios orientales (opuntios), en la costa frente a Eubea. Era la patria de Áyax hijo de Oileo y, según la Ilíada, de Patroclo. Los locrios enviaban cada año dos doncellas a servir en el templo de Atenea en Ilión como expiación por el sacrilegio de Áyax contra Casandra, costumbre que duró siglos.',
   intro:'Perdona que no te atienda mejor: mi hija se va a Troya con la próxima nave y no sé ni lo que hago. Soy Nicareta.',
   topics:[['¿Por qué se va tu hija a Troya?','Porque le ha tocado. Cada año, por sorteo entre las cien casas nobles, dos muchachas locrias van a servir a Atenea en Ilión, para pagar lo que hizo Áyax cuando arrancó a Casandra del altar. Allí barren el templo, descalzas, con el pelo cortado, hasta que llegan otras dos a sustituirlas.'],
    ['¿Es peligroso?','Eso dicen las viejas historias: que los de Ilión esperan en la playa con piedras y que las chicas tienen que llegar de noche, por caminos escondidos, hasta el templo. Hoy los de Ilión son gente pacífica. Pero una madre no duerme igual.']],
   quiz:{q:'¿Por qué enviaban los locrios doncellas al templo de Atenea en Troya?',a:['Para expiar el sacrilegio de Áyax, que arrancó a Casandra del altar','Para casarlas con troyanos','Para aprender a tejer'],ko:'No: era una expiación por el sacrilegio de Áyax hijo de Oileo contra Casandra en el templo de Atenea.'}},
  src:{a:['Ilíada II 527-535 y XXIII 85-90','Polibio XII 5','Estrabón XIII 1.40','Eneas el Táctico XXXI 24'],m:['F. Graf, «Die lokrischen Mädchen», Studi Storico-Religiosi 2 (1978)'],n:['Nicareta es inventada.','Las fuentes no se ponen de acuerdo sobre cuándo empezó y cuándo se interrumpió la costumbre; parece que seguía en el siglo IV.']}},

 {id:'sicion',pos:[22.72,37.98],links:[['corinto','sicion'],['sicion','egio']],
  cfg:{site:[90,-110,22],houses:30,spread:100,temple:{name:'Templo de Apolo',W:12,L:24,nW:6,nL:12}},
  steles:[['sicion_clistenes','Clístenes de Sición','ΚΛΕΙΣΘΕΝΗΣ','Hace casi dos siglos, el tirano Clístenes gobernaba aquí. Heródoto cuenta que, para casar a su hija Agarista, invitó durante un año a los mejores jóvenes de Grecia y los puso a prueba. El ateniense Hipoclides, que iba ganando, bailó cabeza abajo sobre una mesa y perdió la novia: «A Hipoclides no le importa», contestó. El hijo de Agarista fue Clístenes de Atenas, el padre de la democracia.'],
   ['sicion_pintura','La escuela de pintura','ΖΩΓΡΑΦΙΑ','Sición es famosa por sus pintores. El maestro Eupompo enseña aquí con tanto éxito que, según Plinio, se empezó a hablar de tres escuelas de pintura en Grecia: la jonia, la ática y la de Sición. Y en un taller de broncistas de la ciudad corre un niño de unos cuatro años que se llamará Lisipo y será el escultor de Alejandro Magno.']],
  vida:{kinds:['olive','plane','olive','cypress'],fauna:[['dog',2],['hen',4],['pig',2]],barks:['Los pepinos de Sición son los mejores de Grecia, ¡pregunta a cualquiera!','En el taller de Eupompo no cabe un alumno más.','Desde la acrópolis se ve el golfo de Corinto entero.']},
  npc:{id:'nicostrato_sicion',name:'Nicóstrato',title:'Aprendiz de pintor',glyph:'Ν',look:{chiton:'#d8c9a8',himation:'#7a3a2a',hair:'#5a3a22'},
   cat:'Arte',lesson:'Sición y la pintura griega',where:'En Sición, junto a la llegada',
   summary:'Sición, entre Corinto y Acaya, fue una de las grandes ciudades del arte griego. En el siglo VI la gobernó el tirano Clístenes, abuelo materno del Clístenes de Atenas. A comienzos del siglo IV el pintor Eupompo fundó una escuela tan prestigiosa que se habló de una escuela sicionia junto a la jonia y la ática; allí estudió Pánfilo, maestro de Apeles. De Sición era también el escultor Lisipo.',
   intro:'¡No toques, que está fresca! Es una tabla para un exvoto. Soy Nicóstrato, aprendiz en el taller de Eupompo. Bueno, aprendiz: de momento muelo colores y barro el suelo.',
   topics:[['¿Cómo se pinta?','Sobre tablas de madera blanqueadas, casi siempre. Mezclamos los colores con huevo o con cola, y para lo que tiene que durar al sol, con cera caliente: es la encáustica. Los colores son pocos: el blanco de Melos, el ocre amarillo, el rojo de Sinope y el negro de humo. Con eso hay que pintarlo todo.'],
    ['¿Qué enseña tu maestro?','Eupompo dice que no hay que imitar a otros artistas, sino a la naturaleza. Señaló a la gente de la calle y dijo: «Ese es tu modelo». Y enseña dibujo, mucho dibujo, antes de dejarte tocar un color.']],
   quiz:{q:'¿Por qué era famosa Sición en el siglo IV?',a:['Por su escuela de pintura','Por sus minas de plata','Por su flota de guerra'],ko:'No: Sición era famosa por sus pintores; la escuela de Eupompo era tan conocida que se hablaba de una escuela sicionia.'}},
  src:{a:['Heródoto V 67-68 y VI 126-131','Plinio, Historia natural XXXV 75-77','Plinio, Historia natural XXXIV 61'],m:[],n:['Nicóstrato es inventado.','La frase de Eupompo sobre imitar a la naturaleza la recoge Plinio (XXXIV 61).','Lisipo nació hacia el 390: en el 386 sería un niño.']}},

 {id:'itaca',pos:[20.67,38.4],
  cfg:{site:[-80,-120,20],houses:12,spread:70},
  steles:[['itaca_ulises','La isla de Ulises','ΟΔΥΣΣΕΥΣ','«Es áspera, pero buena criadora de jóvenes», dice Ulises de su isla en la Odisea. Ítaca es pequeña, rocosa, con cabras y pocos campos. Aquí volvió Ulises tras veinte años, disfrazado de mendigo, y aquí lo esperaba Penélope tejiendo y destejiendo el sudario de Laertes.'],
   ['itaca_cueva','La cueva de las Ninfas','ΝΥΜΦΑΙ','En la Odisea, los feacios dejan a Ulises dormido en una playa de Ítaca con sus regalos, entre ellos trece trípodes de bronce, y él los esconde en la cueva de las Ninfas. En una cueva del norte de la isla, junto a la bahía de Polis, se han encontrado de verdad doce trípodes de bronce muy antiguos y ofrendas a las Ninfas y a Ulises.']],
  vida:{kinds:['olive','cypress','olive','pine'],fauna:[['goat',5],['pig',3],['dog',2]],barks:['¿El palacio de Ulises? Cada viejo te enseñará uno distinto.','Aquí no hay caballos: no hay sitio para correr.','Mis cerdos comen bellotas, como los del porquero Eumeo.']},
  npc:{id:'dolio_itaca',name:'Dolio',title:'Porquero de Ítaca',glyph:'Δ',look:{chiton:'#8a7350',exomis:true,hair:'#6a6a6a',beard:true,staff:true},
   cat:'Mito',lesson:'Ítaca, la patria de Ulises',where:'En Ítaca, junto a la llegada',
   summary:'Ítaca, en el mar Jonio, es la patria de Ulises en la Odisea: una isla pequeña y rocosa, buena para cabras. En la cueva de la bahía de Polis, en el norte, se hallaron doce trípodes de bronce de época geométrica y ofrendas a las Ninfas y, más tarde, a Ulises, que recuerdan los trípodes que el héroe escondió en la cueva de las Ninfas (Odisea XIII).',
   intro:'¿Otro que viene buscando a Ulises? Pues aquí solo hay cerdos, cabras y un viejo. Soy Dolio. Me llamo como el criado de Laertes, para que veas lo que pesa el nombre en esta isla.',
   topics:[['¿Existió Ulises?','Mi abuelo decía que sí, y mi abuela que no. Lo que sé es que en la cueva del norte hay trípodes de bronce tan viejos que nadie sabe quién los puso, y que la gente deja allí ofrendas a las Ninfas y al héroe. Cada uno cree lo que quiere.'],
    ['¿Cómo es la vida aquí?','Dura. La tierra da poco: olivos, algo de vino, cebada en los rellanos. Lo que hay son cabras, cerdos y el mar. Los jóvenes se van a Corcira, a Corinto, a Sicilia… y vuelven contando historias. Eso sí que no ha cambiado desde Ulises.']],
   quiz:{q:'¿Qué se encontró en la cueva de la bahía de Polis, en Ítaca?',a:['Trípodes de bronce y ofrendas a las Ninfas y a Ulises','El arco de Ulises','La tumba de Penélope'],ko:'No: allí se hallaron trípodes de bronce antiguos y ofrendas a las Ninfas y a Ulises, que recuerdan los trípodes que el héroe escondió en la cueva de las Ninfas.'}},
  src:{a:['Odisea IX 21-28 y XIII 96-125 y 361-371','Estrabón X 2.11'],m:['S. Benton, «Excavations in Ithaca III: the cave at Polis», BSA 35 (1934-35)'],n:['Dolio es inventado (el nombre es el de un criado de Laertes en la Odisea).']}},

 {id:'cefalonia',pos:[20.55,38.2],
  cfg:{site:[90,-110,22],houses:24,spread:90,temple:{name:'Santuario de Zeus Eneso',W:10,L:18,nW:6,nL:11}},
  steles:[['cefalonia_tetrapolis','La isla de las cuatro ciudades','ΤΕΤΡΑΠΟΛΙΣ','Cefalenia, la mayor de las islas Jónicas, tiene cuatro ciudades: Pale, Cranios, Same y Pronos. Tucídides cuenta que en el 431, al empezar la guerra, se aliaron con Atenas sin combatir. En la Ilíada, los cefalenios son los guerreros de Ulises: su reino eran Ítaca, Cefalenia y las islas de alrededor.'],
   ['cefalonia_eneso','El monte Eneso','ΑΙΝΟΣ','La cumbre de la isla, cubierta de abetos oscuros, tiene un santuario de Zeus Eneso. Desde arriba se ven Ítaca, Zacinto y las montañas del Peloponeso y de Acarnania. Los marinos la usan para orientarse.']],
  vida:{kinds:['pine','pine','olive','cypress'],fauna:[['goat',4],['dog',2],['hen',3]],barks:['Los de Same y los de Pale no se ponen de acuerdo ni en el tiempo que hace.','Con estos abetos se hacen remos y mástiles.','Ítaca está ahí enfrente: casi se oye ladrar a sus perros.']},
  npc:{id:'agelao_cefalonia',name:'Agelao',title:'Pescador de Same',glyph:'Α',look:{chiton:'#b7a27c',exomis:true,hair:'#2a1a12',beard:true},
   cat:'Geografía',lesson:'Cefalenia y las islas Jónicas',where:'En Cefalenia, junto a la llegada',
   summary:'Cefalenia, la mayor de las islas Jónicas, tenía cuatro ciudades independientes (Pale, Cranios, Same y Pronos). En la Ilíada, los cefalenios eran los guerreros de Ulises. Durante la guerra del Peloponeso se aliaron con Atenas (Tucídides II 30). Las islas Jónicas estaban en la ruta de Grecia a Italia y Sicilia.',
   intro:'Salud. ¿Has visto los delfines al entrar? Eso es buena pesca mañana. Soy Agelao, de Same.',
   topics:[['¿Cuatro ciudades en una isla?','Cuatro, y cada una con su asamblea, sus magistrados y sus monedas. Nos juntamos cuando viene un peligro de fuera; el resto del tiempo nos peleamos por los pastos y por los peces. Así somos los griegos: cada valle quiere ser libre.'],
    ['¿Por dónde pasan los barcos?','Por aquí pasan todos los que van de Grecia a Italia y a Sicilia: bordean la costa, paran en Zacinto o aquí, y luego cruzan desde Corcira, que es lo más estrecho. Los atenienses que fueron contra Siracusa, hace treinta años, pasaron por estas aguas con más de cien trirremes.']],
   quiz:{q:'¿Cuántas ciudades tenía Cefalenia?',a:['Cuatro, independientes entre sí','Una sola, la de Ulises','Ninguna: solo aldeas'],ko:'No: Cefalenia tenía cuatro ciudades independientes, Pale, Cranios, Same y Pronos.'}},
  src:{a:['Tucídides II 30','Ilíada II 631-637','Estrabón X 2.10-15'],m:[],n:['Agelao es inventado.']}},
 {id:'leucade',pos:[20.7,38.83],
  cfg:{site:[100,-120,24],houses:22,spread:90,temple:{name:'Templo de Apolo Leucatas',W:10,L:18,nW:6,nL:11}},
  steles:[['leucade_salto','El salto de Léucade','ΛΕΥΚΑΤΑΣ','En el cabo del sur, sobre un acantilado blanco, está el templo de Apolo Leucatas. Cada año, en la fiesta del dios, se arroja al mar desde la roca a un condenado, con plumas y pájaros atados para frenar la caída, y abajo lo esperan unas barcas para recogerlo y llevarlo lejos: así se aleja el mal de la ciudad. Más tarde se contará que Safo se tiró desde aquí por amor, pero es una leyenda.'],
   ['leucade_istmo','Una isla hecha a mano','ΔΙΟΡΥΓΜΑ','Léucade era una península unida a Acarnania. Los corintios, que fundaron aquí una colonia hace más de dos siglos, cortaron el istmo con un canal, y desde entonces es una isla. En el canal hay tan poca agua que a veces los barcos se arrastran por encima.']],
  vida:{kinds:['olive','cypress','pine','olive'],fauna:[['goat',3],['dog',2],['hen',3]],barks:['Desde la roca del templo se ve Ítaca.','¿Saltar yo? Ni por amor ni por dinero.','Hablamos como en Corinto: somos sus hijos.']},
  npc:{id:'caridemo_leucade',name:'Carídemo',title:'Guardián del templo de Apolo',glyph:'Χ',look:{chiton:'#efe7d8',himation:'#e8dfcc',hair:'#d8d0c0',beard:true},
   cat:'Religión',lesson:'El salto de Léucade',where:'En Léucade, junto a la llegada',
   summary:'Léucade, colonia de Corinto en el mar Jonio, era una península que los corintios convirtieron en isla con un canal. En el cabo meridional, el templo de Apolo Leucatas celebraba un rito de expiación: un condenado era arrojado al mar desde el acantilado con plumas y aves atadas y luego recogido y alejado (Estrabón X 2.9). La leyenda posterior hizo saltar desde allí a Safo.',
   intro:'Que Apolo te guarde. Si vienes a ver el salto, llegas tarde: fue en la fiesta, y el condenado ya está en una barca camino de Acarnania. Soy Carídemo, guardo el templo.',
   topics:[['¿Por qué arrojáis a un hombre al mar?','Para llevarnos el mal de la ciudad. Elegimos a un condenado; le atamos plumas y pájaros vivos para que el viento lo frene, y abajo le esperan barcas. Si sobrevive, lo llevamos lejos y no vuelve. Él se lleva consigo la culpa de todos. Es un rito muy viejo.'],
    ['¿Es verdad lo de los enamorados?','Algunos dicen que quien salta de la roca se cura del amor. Yo he visto saltar a condenados, no a enamorados. Pero los poetas cómicos de Atenas ya hacen chistes con eso, y no me extrañaría que dentro de poco cuenten que saltó la mismísima Safo.']],
   quiz:{q:'¿Para qué se arrojaba a un hombre desde la roca de Léucade?',a:['Para alejar el mal de la ciudad en un rito de expiación','Para demostrar valor en los juegos','Para ofrecérselo a Poseidón'],ko:'No: era un rito de expiación; al condenado se le recogía en barcas y se le alejaba, llevándose el mal de la ciudad.'}},
  src:{a:['Estrabón X 2.8-9','Tucídides III 81 y 94'],m:['G. Nagy, «Phaethon, Sappho’s Phaon, and the White Rock of Leukas», HSCP 77 (1973)'],n:['Carídemo es inventado.','La leyenda de Safo aparece en la comedia del siglo IV (Menandro, La Leucadia) y en Ovidio, Heroidas XV; no es histórica.']}},

 {id:'zacinto',pos:[20.9,37.78],
  cfg:{site:[90,-110,22],houses:22,spread:90,temple:{name:'Santuario de Ártemis',W:10,L:18,nW:6,nL:11}},
  steles:[['zacinto_pez','El lago de la pez','ΠΙΣΣΑ','Heródoto lo vio con sus propios ojos: en Zacinto hay lagunas de las que se saca pez, la brea negra con la que se calafatean los barcos. Se mete una rama de mirto atada a una pértiga, se saca cubierta de pez y se guarda en un hoyo junto a la laguna. Tiene olor a betún y es mejor que la pez de Pieria.'],
   ['zacinto_sagunto','Hijos de Zacinto en Iberia','ΖΑΚΥΝΘΟΣ ΚΑΙ ΣΑΓΟΥΝΤΟΝ','Los zacintios cuentan que unos marinos de la isla fundaron una ciudad en la costa de Iberia, Sagunto. Muchos siglos después, en el 219, Aníbal la sitiará y empezará así la segunda guerra púnica. El historiador romano Tito Livio recogerá la tradición, aunque es muy dudosa.']],
  vida:{kinds:['olive','cypress','plane','olive'],fauna:[['goat',3],['dog',2],['hen',4]],barks:['Cuidado con las manos: la pez no sale ni con aceite.','Los armadores de Corinto pagan bien nuestra brea.','¡Qué verde es esta isla! Ya lo decía Homero: «Zacinto boscosa».']},
  npc:{id:'hiperbio_zacinto',name:'Hiperbio',title:'Sacador de pez',glyph:'Υ',look:{chiton:'#6b5a4a',exomis:true,hair:'#2a1a12',beard:true},
   cat:'Técnica',lesson:'La pez de Zacinto',where:'En Zacinto, junto a la llegada',
   summary:'En Zacinto había manantiales de betún natural de los que se extraía pez para calafatear barcos. Heródoto (IV 195) describe cómo se sacaba con ramas de mirto atadas a pértigas. La pez era imprescindible para impermeabilizar los cascos, las ánforas y los toneles. Una tradición recogida por Livio hacía de los zacintios los fundadores de Sagunto, en Hispania.',
   intro:'No me des la mano, que la tengo negra hasta el codo. Soy Hiperbio. Si quieres saber de dónde sale la brea de vuestros barcos, mira esa laguna.',
   topics:[['¿Para qué sirve la pez?','Para todo lo que tiene que estar seco por dentro: los cascos de las naves, las juntas entre las tablas, el interior de las ánforas de vino, los odres. Sin pez no hay flota. Por eso nos la compran los corintios, los atenienses y quien haga falta.'],
    ['¿Cómo la sacáis?','Con una pértiga larga y una rama de mirto atada en la punta. La metes en el agua, sale negra y pegajosa, y la escurres en un hoyo junto a la orilla. Cuando hay bastante, la pasamos a ánforas. El agua sabe a betún, pero el pozo no se acaba nunca.']],
   quiz:{q:'¿Para qué se usaba la pez de Zacinto?',a:['Para calafatear barcos e impermeabilizar ánforas','Para alumbrar las casas','Para hacer perfumes'],ko:'No: la pez servía sobre todo para calafatear los barcos y para impermeabilizar ánforas y odres.'}},
  src:{a:['Heródoto IV 195','Odisea I 246 y IX 24','Tito Livio XXI 7'],m:[],n:['Hiperbio es inventado.']}},

 {id:'tasos',pos:[24.71,40.78],
  cfg:{site:[90,-110,24],houses:30,spread:100,temple:{name:'Santuario de Heracles',W:11,L:20,nW:6,nL:11}},
  steles:[['tasos_oro','El oro de Tasos','ΧΡΥΣΕΙΑ','Tasos es rica: tiene minas de oro en la isla y, sobre todo, en la costa de enfrente, en Tracia. Heródoto vio las minas que abrieron los fenicios y dice que habían removido un monte entero. Cuando los tasios se rebelaron contra Atenas en el 465, los atenienses los sitiaron más de dos años y les quitaron las minas de la costa.'],
   ['tasos_arquiloco','El poeta soldado','ΑΡΧΙΛΟΧΟΣ','Hace unos tres siglos llegaron aquí colonos de Paros. Uno de ellos era el poeta Arquíloco, que escribió que había tirado su escudo en una batalla para salvar la vida: «Que se lo quede un tracio; ya me compraré otro igual». De Tasos era también Polignoto, el gran pintor que decoró la Estoa Pintada de Atenas.']],
  vida:{kinds:['pine','olive','pine','plane'],fauna:[['goat',3],['dog',2],['hen',3],['pig',2]],barks:['El vino de Tasos se vende con sello en el asa: el nuestro no se falsifica.','En la costa de Tracia hay más oro que aquí, pero también más tracios.','¿Mármol blanco? Aquí sobra.']},
  npc:{id:'ariston_tasos',name:'Aristón',title:'Comerciante de vino',glyph:'Α',look:{chiton:'#e9dfcb',himation:'#7a3a2a',hair:'#3a2a1e',beard:true},
   cat:'Economía',lesson:'Tasos: oro, vino y Arquíloco',where:'En Tasos, junto a la llegada',
   summary:'Tasos, en el norte del Egeo, fue colonizada por Paros en el siglo VII; entre los colonos estaba el poeta Arquíloco. Su riqueza venía de las minas de oro de la isla y de la costa tracia y de su vino, que se exportaba en ánforas con sello oficial en el asa. Se rebeló contra Atenas en el 465 y fue sometida tras un asedio de más de dos años (Tucídides I 100-101).',
   intro:'¡Prueba, prueba! Vino de Tasos, el que se bebe en los banquetes de Atenas. Soy Aristón, y esta ánfora lleva el sello de la ciudad: nada de mezclas.',
   topics:[['¿Qué es el sello del asa?','La ciudad marca las ánforas antes de cocerlas, con el nombre del magistrado del año y un símbolo. Así se sabe que es vino de Tasos y no de otra parte. Y hay leyes: no se puede comprar uva en la cepa antes de la vendimia, ni descargar vino de fuera en nuestra costa.'],
    ['¿Y el oro?','La isla tiene minas, pero lo bueno está enfrente, en Tracia, junto al monte Pangeo. Por esas minas vinieron los atenienses a quitárnoslas hace ochenta años. El oro trae dinero, pero también enemigos.']],
   quiz:{q:'¿De dónde venía la riqueza de Tasos?',a:['De sus minas de oro y de su vino','De la pesca del atún','Del tributo de Atenas'],ko:'No: Tasos se enriqueció con las minas de oro de la isla y de la costa tracia y con su vino.'}},
  src:{a:['Heródoto II 44 y VI 46-47','Tucídides I 100-101','Arquíloco, fr. 5 West'],m:['Y. Garlan, Les timbres amphoriques de Thasos (1999)'],n:['Aristón es inventado.','Las leyes del vino de Tasos se conocen por inscripciones de finales del siglo V (IG XII Suppl. 347).']}},

 {id:'lemnos',pos:[25.12,39.9],
  cfg:{site:[80,-120,22],houses:26,spread:90,temple:{name:'Santuario de Hefesto',W:10,L:18,nW:6,nL:11}},
  steles:[['lemnos_hefesto','Donde cayó Hefesto','ΗΦΑΙΣΤΟΣ','En la Ilíada, Hefesto cuenta que Zeus, enfadado, lo agarró por un pie y lo arrojó desde el Olimpo: cayó durante todo un día y aterrizó en Lemnos al ponerse el sol, medio muerto. Los sintios, los antiguos habitantes, lo cuidaron. Por eso la ciudad del este se llama Hefestia.'],
   ['lemnos_paz','Las islas de Atenas','ΕΙΡΗΝΗ ΒΑΣΙΛΕΩΣ','Este mismo año, la paz que ha impuesto el rey de Persia dice que todas las ciudades griegas serán libres, excepto tres islas que seguirán siendo de Atenas: Lemnos, Imbros y Esciros. Aquí viven colonos atenienses desde que Milcíades conquistó la isla hace más de un siglo.']],
  vida:{kinds:['olive','plane','olive','cypress'],fauna:[['goat',3],['dog',2],['hen',4],['pig',2]],barks:['Mi abuelo vino de Atenas con un lote de tierra. Ahora soy lemnio y ateniense a la vez.','En Hefestia hay herreros desde siempre.','Esta tierra roja cura heridas, dicen los viejos.']},
  npc:{id:'filocoro_lemnos',name:'Filócoro',title:'Colono ateniense',glyph:'Φ',look:{chiton:'#d8c9a8',himation:'#4f6a7d',hair:'#3a2a1e',beard:true},
   cat:'Política',lesson:'La paz del Rey y las islas de Atenas',where:'En Lemnos, junto a la llegada',
   summary:'Lemnos, en el norte del Egeo, fue conquistada por el ateniense Milcíades hacia el 500 y repoblada con colonos (clerucos) atenienses. En la paz del Rey o de Antálcidas (387/386), el rey persa Artajerjes II impuso la autonomía de las ciudades griegas, pero dejó a Atenas Lemnos, Imbros y Esciros (Jenofonte, Helénicas V 1.31). En el mito, Hefesto cayó en Lemnos al ser arrojado del Olimpo.',
   intro:'¡Un ateniense! O casi: se te nota el acento del Pireo. Soy Filócoro. Mi familia tiene aquí tierras desde hace cuatro generaciones, y gracias a la paz de este año, seguirán siendo nuestras.',
   topics:[['¿Qué dice la paz del Rey?','Que las ciudades de Asia son del rey de Persia; que todas las demás ciudades griegas, grandes y pequeñas, serán autónomas; y que Lemnos, Imbros y Esciros serán de Atenas, como antes. Quien no la acepte tendrá al Rey como enemigo. La trajo el espartano Antálcidas desde Susa. A muchos en Atenas no les gusta, pero a nosotros nos salva las tierras.'],
    ['¿Qué es un cleruco?','Un ciudadano ateniense que recibe un lote de tierra, un cleros, en un territorio conquistado. Sigue siendo ateniense, vota en Atenas si va, y aquí vigila la isla. Los de Lemnos combatimos como atenienses: hace cuarenta años, lemnios e imbrios fueron con Cleón a Pilos y tomaron Esfacteria.']],
   quiz:{q:'¿Qué islas dejó a Atenas la paz del Rey del 387/386?',a:['Lemnos, Imbros y Esciros','Egina, Salamina y Eubea','Delos, Naxos y Paros'],ko:'No: la paz del Rey dejó a Atenas solo Lemnos, Imbros y Esciros.'}},
  src:{a:['Jenofonte, Helénicas V 1.31','Ilíada I 590-594','Heródoto VI 136-140','Tucídides IV 28.4'],m:[],n:['Filócoro es inventado.','La «tierra de Lemnos», usada como medicina, la describirá Galeno en el siglo II d.C.']}},

 {id:'samotracia',pos:[25.53,40.5],
  cfg:{site:[90,-120,26],houses:16,spread:80,temple:{name:'Santuario de los Grandes Dioses',W:12,L:22,nW:6,nL:12}},
  steles:[['samotracia_misterios','Los Grandes Dioses','ΘΕΟΙ ΜΕΓΑΛΟΙ','En Samotracia se celebran misterios en honor de los Grandes Dioses, los Cabiros. A diferencia de los de Eleusis, aquí se puede iniciar cualquiera: hombres, mujeres, esclavos, griegos o bárbaros. Los iniciados creen que los dioses los protegen en el mar, y muchos marinos vienen a iniciarse antes de un viaje largo.'],
   ['samotracia_exvotos','Los que se ahogaron','ΔΙΑΓΟΡΑΣ','En el santuario cuelgan las ofrendas de los que se salvaron de naufragios después de rezar a los Grandes Dioses. Se cuenta que alguien le enseñó esos exvotos a Diágoras de Melos, el ateo, como prueba de que los dioses existen, y él contestó: «Habría muchos más si los hubieran dejado también los que se ahogaron».']],
  vida:{kinds:['plane','olive','pine','cypress'],fauna:[['goat',4],['dog',2],['hen',3]],barks:['Desde la cumbre de esta isla, dice Homero, Poseidón miraba la guerra de Troya.','El que entra en el santuario sin iniciarse no vuelve a ser el mismo, dicen.','¿Te vas a iniciar? Hay que confesar la peor cosa que hayas hecho.']},
  npc:{id:'teocles_samotracia',name:'Teocles',title:'Iniciador de los Misterios',glyph:'Θ',look:{chiton:'#efe7d8',himation:'#5a3a6a',hair:'#d8d0c0',beard:true},
   cat:'Religión',lesson:'Los Misterios de Samotracia',where:'En Samotracia, junto a la llegada',
   summary:'En Samotracia, en el norte del Egeo, se celebraban los misterios de los Grandes Dioses (Cabiros), abiertos a todos, incluidos esclavos y extranjeros. Se creía que protegían a los navegantes. Heródoto (II 51) ya los conoce. La anécdota de Diágoras de Melos sobre los exvotos de los náufragos la cuenta Cicerón (De natura deorum III 89). La famosa Victoria de Samotracia se esculpirá hacia el 190 a.C.',
   intro:'Bienvenido a la isla de los Grandes Dioses. Soy Teocles. No te diré lo que pasa dentro: eso solo lo saben los iniciados. Pero puedo contarte lo que cualquiera sabe.',
   topics:[['¿Quién puede iniciarse?','Cualquiera que llegue con buena voluntad: hombres y mujeres, libres y esclavos, griegos y extranjeros. Primero hay una purificación y una confesión ante el sacerdote; luego, de noche, a la luz de las antorchas, ves lo que tienes que ver. Al salir te dan una cinta de púrpura para atarte a la cintura.'],
    ['¿Te protegen de verdad en el mar?','Mira las paredes del santuario: anclas, remos, tablillas con naves pintadas. Son de los que se salvaron. Diágoras dijo que faltaban los de los ahogados. Bueno, Diágoras ya no está entre nosotros, y yo sigo aquí.']],
   quiz:{q:'¿Qué tenían de especial los Misterios de Samotracia?',a:['Que podía iniciarse cualquiera, incluidos esclavos y extranjeros, y protegían a los marinos','Que solo podían iniciarse los reyes','Que se celebraban en Atenas'],ko:'No: estaban abiertos a todos, incluso a esclavos y extranjeros, y se creía que protegían a los navegantes.'}},
  src:{a:['Heródoto II 51','Cicerón, De natura deorum III 89','Diógenes Laercio VI 59','Ilíada XIII 10-14'],m:['S. G. Cole, Theoi Megaloi: The Cult of the Great Gods at Samothrace (1984)'],n:['Teocles es inventado.','La cinta de púrpura de los iniciados la menciona el escoliasta de Apolonio de Rodas (I 917).']}},

 {id:'cos',pos:[26.97,36.75],
  cfg:{site:[90,-110,22],houses:24,spread:90,temple:{name:'Santuario de Asclepio',W:10,L:18,nW:6,nL:11}},
  steles:[['cos_hipocrates','El médico de Cos','ΙΠΠΟΚΡΑΤΗΣ','Hipócrates nació en esta isla hace unos setenta y cinco años, en una familia de médicos que dicen descender de Asclepio. Enseñó que las enfermedades tienen causas naturales, no castigos de los dioses, y que el médico debe observar al enfermo, anotar lo que ve y, ante todo, no hacer daño. Hoy es muy viejo; se dice que vive en Tesalia.'],
   ['cos_juramento','El juramento','ΟΡΚΟΣ','Los que aprenden medicina con los asclepíadas de Cos juran por Apolo médico, por Asclepio, por Higiea y por Panacea: tratar a sus maestros como a padres, no dar veneno aunque se lo pidan, no aprovecharse de los enfermos y callar lo que vean en las casas.']],
  vida:{kinds:['olive','cypress','plane','olive'],fauna:[['goat',3],['dog',2],['hen',4]],barks:['Aquí vienen enfermos de toda Grecia y de Asia.','La seda de Cos es tan fina que se transparenta: los moralistas se escandalizan.','Mi primo estudia con los asclepíadas: ya no habla de otra cosa que de humores.']},
  npc:{id:'polibo_cos',name:'Pólibo',title:'Médico, yerno de Hipócrates',glyph:'Π',look:{chiton:'#efe7d8',himation:'#e8dfcc',hair:'#6a6a6a',beard:true,staff:true},
   cat:'Ciencia',lesson:'Hipócrates y la medicina griega',where:'En Cos, junto a la llegada',
   summary:'Cos, en el Dodecaneso, fue la patria de Hipócrates (c. 460-370), el médico más famoso de la Antigüedad, de la familia de los asclepíadas. La medicina hipocrática explicaba las enfermedades por causas naturales, como el desequilibrio de los humores, y se basaba en la observación del enfermo. Pólibo, su yerno, es el autor probable del tratado Sobre la naturaleza del hombre. El gran Asclepieion de Cos se construirá algo más tarde, desde finales del siglo IV.',
   intro:'Siéntate, siéntate: tienes cara de no haber dormido en el barco. Soy Pólibo. Mi suegro, Hipócrates, me enseñó que antes de hablar hay que mirar. Déjame mirarte.',
   topics:[['¿Qué son los humores?','El cuerpo tiene cuatro: sangre, flema, bilis amarilla y bilis negra. Cuando están en equilibrio, estás sano; cuando uno sobra o falta, enfermas. Por eso cambian con las estaciones: en invierno sobra flema y la gente tose; en verano, bilis. El médico ayuda a la naturaleza a recuperar el equilibrio, con dieta, ejercicio, baños y, solo si hace falta, con medicinas o cirugía.'],
    ['¿Y la enfermedad sagrada?','Así llaman a la epilepsia, como si la mandaran los dioses. Mi suegro escribió que no es más sagrada que las demás: tiene su causa en el cerebro, como todas las enfermedades tienen la suya. Los que la llaman sagrada lo hacen para esconder que no saben curarla.']],
   quiz:{q:'¿Qué enseñaba la medicina hipocrática?',a:['Que las enfermedades tienen causas naturales y hay que observar al enfermo','Que las enfermedades son castigos de los dioses','Que solo los sacerdotes pueden curar'],ko:'No: Hipócrates enseñaba que las enfermedades tienen causas naturales y que el médico debe observar al enfermo.'}},
  src:{a:['Hipócrates, Sobre la enfermedad sagrada 1-2','Pólibo (atribuido), Sobre la naturaleza del hombre 4','Juramento hipocrático','Platón, Protágoras 311b'],m:['J. Jouanna, Hippocrates (1999)'],n:['Pólibo es histórico; su conversación es inventada.','La ciudad de Cos se trasladará al nordeste de la isla en el 366; en el 386 la principal era Astipalea, al oeste.']}},
 {id:'cime',pos:[26.94,38.76],port:[1,0,'Cime'],
  cfg:{site:[60,-120,22],houses:28,spread:100,temple:{name:'Santuario de Apolo',W:10,L:18,nW:6,nL:11}},
  steles:[['cime_eolios','La mayor ciudad eolia','ΑΙΟΛΙΣ','Cime es la más importante de las doce ciudades eolias de la costa de Asia. De aquí salió el padre del poeta Hesíodo, que, empujado por la pobreza, cruzó el mar hasta Ascra, en Beocia: lo cuenta el propio Hesíodo en Los trabajos y los días. Y unos colonos de Cime ayudaron a fundar Cumas, en Italia, la primera colonia griega de Occidente.'],
   ['cime_rey','Otra vez del Rey','ΕΙΡΗΝΗ ΒΑΣΙΛΕΩΣ','La paz de este año dice que las ciudades griegas de Asia pertenecen al rey de Persia. Después de cuarenta años de guerras, Cime vuelve a pagar tributo al sátrapa de Sardes, como antes de las guerras médicas. En la ciudad juega un muchacho de unos catorce años, Éforo, que escribirá la primera historia universal de los griegos.']],
  vida:{kinds:['olive','plane','olive','cypress'],fauna:[['dog',2],['hen',4],['goat',2],['pig',2]],barks:['Dicen que los de Cime somos lentos: tardamos trescientos años en cobrar impuestos al puerto.','El recaudador del sátrapa vuelve el mes que viene.','Hablamos eolio, como Safo y Alceo.']},
  npc:{id:'demodice_cime',name:'Demódice',title:'Viuda de un armador',glyph:'Δ',look:{female:true,chiton:'#e8dfcc',himation:'#6a4a2a',hair:'#5a4a3a'},
   cat:'Política',lesson:'Los griegos de Asia y la paz del Rey',where:'En Cime, en la Eólide',
   summary:'Cime, en la Eólide (costa de Asia Menor), era la mayor ciudad eolia; de allí era el padre de Hesíodo y participó en la fundación de Cumas en Italia. Por la paz del Rey (387/386), las ciudades griegas de Asia quedaron bajo el rey de Persia. Hacia el 400 nació en Cime el historiador Éforo, autor de la primera historia universal griega.',
   intro:'¿Vienes de Atenas? Pues allí habéis firmado que nosotros somos del Rey. No te lo tomo en cuenta: lo firmaron los espartanos. Soy Demódice.',
   topics:[['¿Cómo os afecta la paz?','El sátrapa vuelve a cobrar tributo y a poner guarniciones donde quiere. Los que habíamos confiado en Atenas o en Esparta para ser libres nos hemos quedado solos. Pero el comercio sigue: los persas también necesitan barcos, y mi casa los construye.'],
    ['¿Por qué se ríen de los de Cime?','Porque dicen que tardamos trescientos años en darnos cuenta de que podíamos cobrar por los barcos que atracan en el puerto. Los chistes sobre Cime corren por toda Grecia. Ya verás cuando mi vecino Éforo sea mayor: dicen que escribe tanto que en cada página pondrá «mientras tanto, los de Cime estaban tranquilos».']],
   quiz:{q:'¿Qué pasó con las ciudades griegas de Asia en la paz del Rey (387/386)?',a:['Quedaron bajo el dominio del rey de Persia','Se unieron a Atenas','Se hicieron independientes de todos'],ko:'No: la paz del Rey entregó las ciudades griegas de Asia al rey de Persia.'}},
  src:{a:['Hesíodo, Trabajos y días 633-640','Jenofonte, Helénicas V 1.31','Estrabón XIII 3.6','Heródoto I 149'],m:[],n:['Demódice es inventada.','El chiste de Éforo y los de Cime lo cuenta Estrabón (XIII 3.6).','Éforo nació hacia el 400: en el 386 sería un adolescente.']}},

 {id:'cnido',pos:[27.37,36.69],port:[0,1,'Cnido'],
  cfg:{site:[60,-120,24],houses:26,spread:100,temple:{name:'Santuario de Apolo Triopio',W:11,L:20,nW:6,nL:11}},
  steles:[['cnido_batalla','La batalla de Cnido','ΚΝΙΔΟΣ','Hace ocho años, en el 394, aquí delante, la flota persa mandada por el ateniense Conón y el sátrapa Farnabazo destruyó la de Esparta. El almirante espartano Pisandro murió combatiendo. Con aquella victoria Esparta perdió el mar, y Conón volvió a Atenas con dinero persa para reconstruir los Muros Largos.'],
   ['cnido_triopio','La fiesta de los dorios de Asia','ΤΡΙΟΠΙΟΝ','En el cabo Triopio, junto a Cnido, las ciudades dorias de la costa de Asia celebran juntas los juegos de Apolo Triopio. Los premios son trípodes de bronce, pero el ganador no se los puede llevar: debe dejarlos en el templo. Heródoto cuenta que un atleta de Halicarnaso se llevó el suyo a casa, y por eso expulsaron a su ciudad de la fiesta.']],
  vida:{kinds:['olive','cypress','pine','olive'],fauna:[['dog',2],['hen',4],['goat',3]],barks:['De aquí salen médicos para toda Asia, ¡y hasta para la corte del Rey!','Desde el cabo se ven las velas que van a Rodas y a Egipto.','Mi abuelo vio arder las naves espartanas.']},
  npc:{id:'ctesias_cnido',name:'Ctesias',title:'Médico, vuelto de la corte persa',glyph:'Κ',look:{chiton:'#efe7d8',himation:'#7a2a3a',hair:'#8a8a8a',beard:true},
   cat:'Historia',lesson:'Ctesias y la corte del Rey',where:'En Cnido, junto a la llegada',
   summary:'Cnido, ciudad doria de Caria, tenía una escuela médica rival de la de Cos. El médico Ctesias de Cnido sirvió en la corte de Artajerjes II y curó al rey en la batalla de Cunaxa (401); de vuelta en Grecia escribió unas Pérsicas y unas Índicas llenas de maravillas. En el 394, frente a Cnido, Conón y Farnabazo destruyeron la flota espartana. La Afrodita de Praxíteles llegará a Cnido hacia el 360.',
   intro:'Diecisiete años en Persia y, cuando vuelvo, resulta que todos los griegos creen saber cómo es el Rey. Soy Ctesias. Yo le curé una herida con mis manos.',
   topics:[['¿Cómo es la corte del Rey?','Inmensa. El Rey come solo, detrás de una cortina; la reina madre, Parisátide, manda más que nadie y envenena a quien le estorba. Yo curé al Rey en Cunaxa, cuando su hermano Ciro le hirió en el pecho. Lo estoy escribiendo todo en mis Pérsicas, veintitrés libros. Heródoto, ese mentiroso, no se enteró de nada.'],
    ['¿Y la India?','No he estado, pero he hablado con quien ha estado. Hay hombres con una sola pierna tan grande que se dan sombra con ella, hombres con cabeza de perro y un animal, la mantícora, con cara de hombre, tres filas de dientes y cola de escorpión. Lo pongo todo en mis Índicas. Los que me lo contaron eran gente seria.']],
   quiz:{q:'¿Por qué era famoso Ctesias de Cnido?',a:['Fue médico del rey de Persia y escribió sobre Persia y la India','Fue el almirante de la batalla de Cnido','Esculpió la Afrodita de Cnido'],ko:'No: Ctesias fue médico de Artajerjes II y escribió unas Pérsicas y unas Índicas.'}},
  src:{a:['Jenofonte, Anábasis I 8.26-27','Jenofonte, Helénicas IV 3.10-12','Heródoto I 144','Focio, Biblioteca 72 (resumen de Ctesias)'],m:['L. Llewellyn-Jones y J. Robson, Ctesias’ History of Persia (2010)'],n:['Ctesias es histórico; su conversación es inventada a partir de sus fragmentos.','La fecha de su vuelta a Grecia es dudosa (hacia el 398-397).','La Afrodita de Praxíteles es de hacia el 360: aún no existe.']}},

 {id:'siracusa386',pos:[15.29,37.06],port:[1,0,'Siracusa'],
  isl:{name:'Siracusa',gr:'ΣΥΡΑΚΟΥΣΑΙ · ΣΙΚΕΛΙΑ'},
  cfg:{site:[60,-130,26],houses:50,spread:130,temple:{name:'Templo de Atenea en Ortigia',W:14,L:26,nW:6,nL:13}},
  steles:[['siracusa386_dionisio','El tirano Dionisio','ΔΙΟΝΥΣΙΟΣ','Desde hace casi veinte años manda en Siracusa Dionisio, un antiguo escribano que se hizo tirano con ayuda de mercenarios. Ha rodeado la ciudad con murallas inmensas y ha convertido la isla de Ortigia en su fortaleza. Sus ingenieros inventaron la catapulta para la guerra contra Cartago. Escribe tragedias y las manda a Atenas, donde se ríen de ellas.'],
   ['siracusa386_platon','Platón en Siracusa','ΠΛΑΤΩΝ','Hace un par de años, Platón vino a Sicilia y estuvo en la corte de Dionisio. Le habló de justicia y de que el tirano es el más desgraciado de los hombres. Dionisio se enfadó tanto que, según se cuenta, lo hizo vender como esclavo en Egina; un amigo, Aníceris de Cirene, lo compró y lo liberó. Ahora Platón ha vuelto a Atenas y ha abierto su escuela en la Academia.']],
  vida:{kinds:['olive','cypress','plane','olive'],fauna:[['dog',2],['hen',4],['pig',2],['goat',2]],barks:['Cuidado con lo que dices: el tirano tiene orejas en todas partes.','La fuente de Aretusa es agua dulce a dos pasos del mar.','En las canteras todavía hay huesos de los atenienses de la gran expedición.']},
  npc:{id:'arquipo_siracusa',name:'Arquipo',title:'Platero de Ortigia',glyph:'Α',look:{chiton:'#e9dfcb',himation:'#2f5a7a',hair:'#2a1a12',beard:true},
   cat:'Política',lesson:'Dionisio de Siracusa y Platón',where:'En Siracusa, en Sicilia',
   summary:'Siracusa, colonia corintia, era la mayor ciudad griega de Occidente. Dionisio I la gobernó como tirano del 405 al 367, con un gran ejército de mercenarios, enormes fortificaciones (Ortigia, Epípolas y el castillo de Euríalo) y guerras contra Cartago; en el 399 sus ingenieros inventaron la catapulta. Platón visitó su corte hacia el 388 y salió mal parado; según la tradición, fue vendido como esclavo en Egina.',
   intro:'Habla bajo, extranjero. En Siracusa las paredes oyen. Soy Arquipo; hago copas de plata para los oficiales del tirano. Me pagan bien. No preguntes más.',
   topics:[['¿Cómo es Dionisio?','Listo, desconfiado y valiente. Dicen que duerme rodeado de un foso, que no deja que un barbero le acerque la navaja a la garganta y que sus hijas le queman la barba con cáscaras de nuez. Mantiene a miles de mercenarios y nos ha defendido de Cartago. Pero quien habla mal de él desaparece en las canteras.'],
    ['¿Qué pasó con el filósofo ateniense?','¿Platón? Vino invitado por Dion, el cuñado del tirano, que lo admira. Habló en la corte de que el tirano es el hombre más infeliz, porque vive con miedo. A Dionisio no le gustó nada. Lo embarcaron con un espartano y acabó en el mercado de esclavos de Egina. Lo rescataron, sí. Pero no creo que vuelva.']],
   quiz:{q:'¿Qué le pasó a Platón en la corte de Dionisio de Siracusa, según la tradición?',a:['Lo hicieron vender como esclavo en Egina, y un amigo lo rescató','Lo nombraron consejero del tirano','Se casó con una hija de Dionisio'],ko:'No: según la tradición, Dionisio se enfadó con él y lo hizo vender como esclavo en Egina, donde Aníceris lo compró y lo liberó.'}},
  src:{a:['Diodoro XIV 7, 18 y 41-42; XV 7','Platón, Carta VII 324-326','Diógenes Laercio III 18-21','Cicerón, Tusculanas V 57-63'],m:['B. Caven, Dionysius I, War-Lord of Sicily (1990)'],n:['Arquipo es inventado.','La venta de Platón como esclavo es una tradición tardía y discutida.']}},

 {id:'tarento',pos:[17.24,40.47],port:[0,1,'Tarento'],
  cfg:{site:[60,-130,24],houses:40,spread:120,temple:{name:'Templo de Poseidón',W:12,L:24,nW:6,nL:12}},
  steles:[['tarento_partenios','Los hijos de las doncellas','ΠΑΡΘΕΝΙΑΙ','Tarento la fundaron los espartanos hace más de tres siglos. Se cuenta que los fundadores fueron los partenios, «hijos de doncellas»: nacidos durante una larga guerra en Mesenia, mientras sus padres estaban fuera, y despreciados por ello en Esparta. El oráculo de Delfos le dijo a su jefe, Falanto, que fundaría una ciudad donde viera llover con el cielo despejado. En Italia, abatido, apoyó la cabeza en las rodillas de su mujer, que se llamaba Etra («cielo despejado»), y ella lloró sobre él: la lluvia del oráculo.'],
   ['tarento_arquitas','Arquitas, el general filósofo','ΑΡΧΥΤΑΣ','Tarento la gobierna Arquitas, un pitagórico que es a la vez matemático, músico y general, y nunca ha perdido una batalla. Resolvió el problema de duplicar el cubo con una construcción en tres dimensiones. Se cuenta que fabricó una paloma de madera que volaba. Es amigo de Platón, que lo visitó hace un par de años.']],
  vida:{kinds:['olive','plane','cypress','olive'],fauna:[['dog',2],['hen',4],['pig',2],['goat',2]],barks:['La púrpura de Tarento es casi tan buena como la de Tiro.','Arquitas no deja que se azote a los esclavos cuando está enfadado: dice que espera a calmarse.','Nuestra flota es la mayor de Italia.']},
  npc:{id:'arquitas_tarento',name:'Arquitas',title:'Estratego y matemático',glyph:'Α',look:{chiton:'#efe7d8',himation:'#e8dfcc',hair:'#5a4a3a',beard:true},
   cat:'Ciencia',lesson:'Arquitas y los pitagóricos de Tarento',where:'En Tarento, en la Magna Grecia',
   summary:'Tarento, colonia espartana en el sur de Italia, era a comienzos del siglo IV la ciudad más poderosa de la Magna Grecia. La gobernó Arquitas (c. 428-347), filósofo pitagórico, matemático (resolvió la duplicación del cubo), teórico de la música y general invicto, elegido estratego siete veces. Fue amigo de Platón, a quien rescató de Dionisio II en el 361. La tradición le atribuye una paloma mecánica que volaba.',
   intro:'Bienvenido a Tarento. Soy Arquitas. Si eres amigo de Platón, eres amigo mío; si eres amigo de Dionisio, también, pero un poco menos.',
   topics:[['¿Qué es la duplicación del cubo?','Un problema de Delos: el oráculo pidió un altar del doble de volumen que el que había. Doblar el lado no sirve: el volumen se hace ocho veces mayor. Hay que encontrar una longitud que multiplicada tres veces por sí misma dé el doble. Yo la encontré cortando un cilindro, un cono y un toro, como si cortara un pan con tres cuchillos a la vez.'],
    ['¿Es verdad lo de la paloma?','Es un juguete: una paloma de madera, hueca y bien equilibrada, que se mueve con aire encerrado. Vuela un trecho y cae. No puede volver a levantarse sola. A los niños les encanta. A mí me interesa más por qué vuela que el que vuele.'],
    ['¿Para qué sirven los números?','Para todo. La música son proporciones: la octava es 2 a 1; la quinta, 3 a 2; la cuarta, 4 a 3. Y la ciudad también: cuando el rico y el pobre saben calcular lo que es justo, dejan de pelearse. El cálculo, digo yo, es lo que hace posible la concordia.']],
   quiz:{q:'¿Quién era Arquitas de Tarento?',a:['Un pitagórico, matemático, músico y general, amigo de Platón','El tirano de Siracusa','El fundador espartano de Tarento'],ko:'No: Arquitas fue un filósofo pitagórico, matemático y general que gobernó Tarento y fue amigo de Platón.'}},
  src:{a:['Diógenes Laercio VIII 79-83','Aulo Gelio X 12.8-10','Eutocio, Comentario a Arquímedes, Esfera y cilindro II (la duplicación del cubo)','Arquitas, fr. 1-3 Huffman','Estrabón VI 3.2-4','Pausanias X 10.6-8'],m:['C. Huffman, Archytas of Tarentum (2005)'],n:['Arquitas es histórico; su conversación es inventada a partir de sus fragmentos.','La paloma mecánica la cuenta Aulo Gelio en el siglo II d.C.; es una tradición dudosa.']}},
 {id:'cirene',pos:[21.86,32.82],port:[0,1,'Apolonia, el puerto de Cirene'],
  isl:{name:'Cirene',gr:'ΚΥΡΗΝΗ · ΛΙΒΥΗ'},
  cfg:{site:[60,-120,26],houses:36,spread:110,temple:{name:'Templo de Apolo',W:13,L:26,nW:6,nL:13}},
  steles:[['cirene_tera','Los colonos de Tera','ΒΑΤΤΟΣ','Hace unos dos siglos y medio, la pequeña isla de Tera, sin lluvia durante siete años, obedeció al oráculo de Delfos y envió colonos a Libia con un tal Bato. Se instalaron en esta meseta verde, junto a una fuente sagrada de Apolo. Heródoto cuenta la historia dos veces: como la cuentan los tereos y como la cuentan los cireneos.'],
   ['cirene_silfio','El silfio','ΣΙΛΦΙΟΝ','Cirene es rica gracias a una planta que solo crece aquí y que nadie ha conseguido cultivar: el silfio. Su jugo es condimento y medicina para casi todo, y se paga a precio de plata. Lo llevan dibujado sus monedas. Dentro de unos siglos ya no quedará: los romanos dirán que el último tallo se lo regalaron a Nerón.']],
  vida:{kinds:['olive','cypress','pine','olive'],fauna:[['dog',2],['hen',3],['goat',4]],barks:['Aquí llueve, no como en el resto de Libia: por eso vinimos.','Los carros de Cirene ganan en Olimpia y en Delfos.','Aristipo, el de la escuela de Atenas, es de aquí. Dice que el placer es el bien. ¡Así cualquiera!']},
  npc:{id:'filotera_cirene',name:'Filótera',title:'Vendedora de silfio',glyph:'Φ',look:{female:true,chiton:'#e8dfcc',himation:'#8a6a2a',hair:'#3b2a1e'},
   cat:'Economía',lesson:'Cirene y el silfio',where:'En Cirene, en Libia',
   summary:'Cirene, en la costa de Libia, fue fundada hacia el 631 por colonos de Tera guiados por Bato (Heródoto IV 150-158). Su riqueza procedía del silfio, una planta silvestre que solo crecía allí y no se lograba cultivar, usada como condimento y medicina; aparece en sus monedas. Se extinguió en época romana. De Cirene eran el filósofo Aristipo y el matemático Teodoro, maestro de Platón.',
   intro:'¡Silfio fresco! Bueno, fresco no, que el tallo no aguanta el viaje. El jugo, en cambio, dura años. Soy Filótera. ¿Para la tos, para el estómago o para la comida?',
   topics:[['¿Qué tiene de especial el silfio?','Que solo crece aquí, en los montes de detrás de la ciudad, y que no hay manera de plantarlo: si lo siembras, no sale. Así que lo recogemos, sacamos el jugo de la raíz y del tallo y lo secamos. Se usa para todo: para dar sabor, para la fiebre, para las heridas, para que las ovejas engorden. Vale tanto como la plata.'],
    ['¿Quiénes son los sabios de Cirene?','Teodoro, el matemático, que demostró que hay longitudes que no se pueden medir con números enteros ni con fracciones; Platón vino a aprender con él. Y Aristipo, que estudió con Sócrates en Atenas y ahora enseña que el placer del momento es el bien supremo. Mi marido dice que eso ya lo sabía él sin ir a Atenas.']],
   quiz:{q:'¿De dónde venía la riqueza de Cirene?',a:['Del silfio, una planta medicinal que solo crecía allí','De las minas de oro','Del comercio de esclavos con Persia'],ko:'No: Cirene se enriqueció con el silfio, una planta silvestre que solo crecía allí y se pagaba a precio de plata.'}},
  src:{a:['Heródoto IV 150-159','Teofrasto, Historia de las plantas VI 3','Plinio, Historia natural XIX 38-46','Platón, Teeteto 147d'],m:[],n:['Filótera es inventada.','La extinción del silfio la cuenta Plinio: el último tallo se lo enviaron a Nerón.']}},

 {id:'olbia',pos:[31.9,46.69],port:[1,0,'Olbia'],
  isl:{name:'Olbia',gr:'ΟΛΒΙΑ · ΠΟΝΤΟΣ'},
  cfg:{site:[60,-120,22],houses:30,spread:110,temple:{name:'Templo de Apolo Delfinio',W:11,L:20,nW:6,nL:11}},
  steles:[['olbia_borystenes','La ciudad del Borístenes','ΒΟΡΥΣΘΕΝΗΣ','Olbia, la «feliz», la fundaron colonos de Mileto en la desembocadura del Hípanis y del Borístenes, el gran río de Escitia. Heródoto vino aquí y dice que el Borístenes es el río más productivo después del Nilo: pastos excelentes, pesca abundante y una sal que se forma sola en su boca. De aquí sale trigo, pescado salado y esclavos hacia Grecia.'],
   ['olbia_escilas','El rey que quería ser griego','ΣΚΥΛΗΣ','Heródoto cuenta la historia de Escilas, un rey escita que tenía casa en Olbia. Cuando venía a la ciudad, dejaba a su ejército fuera, se quitaba la ropa escita, se vestía a la griega y vivía como un griego. Se inició en los misterios de Dioniso. Los escitas lo vieron dando saltos en la procesión báquica y lo mataron por traidor a las costumbres de sus padres.']],
  vida:{kinds:['plane','pine','plane','cypress'],fauna:[['dog',2],['hen',4],['pig',3]],barks:['En invierno el mar se hiela y se puede cruzar a pie a la otra orilla.','Los escitas cambian trigo por vino y por joyas de oro.','Aquí rezamos a Apolo Delfinio y a Aquiles, el señor del mar Negro.']},
  npc:{id:'sirisco_olbia',name:'Sirisco',title:'Mercader de trigo',glyph:'Σ',look:{chiton:'#d8c9a8',himation:'#5a6a3a',hair:'#3a2a1e',beard:true},
   cat:'Economía',lesson:'Olbia: griegos y escitas',where:'En Olbia, en el Ponto',
   summary:'Olbia, colonia de Mileto en la desembocadura del Hípanis (Bug) y el Borístenes (Dniéper), en el norte del mar Negro, comerciaba con los escitas: exportaba trigo, pescado salado y esclavos a Grecia e importaba vino, aceite, cerámica y orfebrería. Heródoto la visitó y cuenta la historia del rey escita Escilas, asesinado por adoptar costumbres griegas (IV 78-80).',
   intro:'¿Vienes del sur? Pues dile a los atenienses que este año hay trigo de sobra, pero que lo paguen en plata, no en promesas. Soy Sirisco.',
   topics:[['¿Cómo son los escitas?','Viven a caballo y en carros, con sus rebaños. Beben la leche de las yeguas y entierran a sus reyes con caballos, criados y montones de oro. Los del interior no quieren saber nada de nosotros; los de la costa negocian y algunos hasta hablan griego. A todos les gusta el vino, y lo beben sin agua, cosa que en Grecia se considera de bárbaros.'],
    ['¿Qué le vendéis a Grecia?','Trigo, sobre todo: la llanura de Escitia da más grano del que pueden comer. También pescado salado, esturiones enormes del río, pieles, miel, cera y esclavos. A cambio nos traen vino de Quíos y de Tasos, aceite, vasos pintados de Atenas y joyas que los orfebres hacen al gusto escita, con ciervos y grifos.']],
   quiz:{q:'¿Qué exportaba Olbia a Grecia?',a:['Trigo, pescado salado y esclavos','Aceite de oliva y vino','Mármol y plata'],ko:'No: Olbia enviaba a Grecia trigo, pescado salado, pieles y esclavos, y compraba vino, aceite y cerámica.'}},
  src:{a:['Heródoto IV 17-18, 53 y 76-80','Dión de Prusa, Discurso XXXVI (Boristenítico)'],m:['J. G. F. Hind, «Greek and barbarian peoples on the shores of the Black Sea», Archaeological Reports 30 (1984)'],n:['Sirisco es inventado.','El culto a Aquiles Pontarca en Olbia está atestiguado por inscripciones.']}},

 {id:'panticapeo',pos:[36.47,45.35],port:[1,0,'Panticapeo'],
  isl:{name:'Panticapeo',gr:'ΠΑΝΤΙΚΑΠΑΙΟΝ · ΒΟΣΠΟΡΟΣ'},
  cfg:{site:[60,-130,26],houses:34,spread:110,temple:{name:'Templo de Apolo Médico',W:11,L:20,nW:6,nL:11}},
  steles:[['panticapeo_leucon','El rey Leucón','ΛΕΥΚΩΝ','Panticapeo, colonia de Mileto en el Bósforo Cimerio, es la capital de un reino. Desde hace unos tres años reina Leucón, que manda sobre los griegos de las dos orillas del estrecho y sobre los pueblos de alrededor. Por amistad con Atenas, los barcos que cargan trigo para el Pireo no pagan impuestos aquí y cargan los primeros.'],
   ['panticapeo_trigo','El granero de Atenas','ΣΙΤΟΣ','Atenas no produce todo el trigo que come. Una parte muy grande viene de aquí: según Demóstenes, unos cuatrocientos mil medimnos al año, tanto como todo lo que llega de los demás sitios juntos. Por eso Atenas vigila el Helesponto y el Bósforo: si cortan esta ruta, la ciudad pasa hambre, como ocurrió el año pasado.']],
  vida:{kinds:['plane','pine','plane','olive'],fauna:[['dog',2],['hen',4],['pig',2],['goat',2]],barks:['En invierno el estrecho se hiela y pasan carros sobre el mar.','Los atenienses pagan tarde, pero pagan.','El rey Leucón tiene más mercenarios que la mitad de Grecia.']},
  npc:{id:'estratocles_panticapeo',name:'Estratocles',title:'Armador ateniense',glyph:'Σ',look:{chiton:'#d8c9a8',himation:'#4f6a7d',hair:'#3a2a1e',beard:true},
   cat:'Economía',lesson:'El trigo del Bósforo',where:'En Panticapeo, en el Bósforo Cimerio',
   summary:'Panticapeo (Kerch, en Crimea), colonia de Mileto, era la capital del reino del Bósforo Cimerio. Leucón I (c. 389/388-349/348) concedió a Atenas la exención de impuestos y la prioridad de carga para el trigo destinado al Pireo; según Demóstenes, de allí venían unos 400.000 medimnos al año (Contra Leptines 31-33). La ruta del mar Negro era vital para el abastecimiento de Atenas.',
   intro:'¡Un compatriota! Llevo tres meses esperando que el trigo esté en los almacenes y el viento sople a favor. Soy Estratocles. Si tienes plata, te hago socio del viaje.',
   topics:[['¿Por qué no pagáis impuestos aquí?','Porque el rey Leucón es amigo de Atenas. Los barcos que cargan para el Pireo están libres de la treintava parte que pagan los demás y cargan antes que nadie. A cambio, Atenas le ha hecho ciudadano honorario, a él y a sus hijos. Es buen negocio para los dos: él vende su trigo y nosotros comemos.'],
    ['¿Cómo se financia un viaje así?','Con un préstamo marítimo. Un rico de Atenas me presta el dinero para comprar la carga, con un interés muy alto, una cuarta o una tercera parte. Pero si el barco se hunde, no le devuelvo nada: el riesgo es suyo. Por eso se escribe un contrato detallado: de dónde a dónde, qué carga, en qué fecha. Más de un pleito ha empezado por un barco que «se hundió» demasiado oportunamente.']],
   quiz:{q:'¿Por qué era tan importante Panticapeo para Atenas?',a:['Porque de allí llegaba gran parte del trigo que Atenas necesitaba','Porque allí se acuñaba la moneda ateniense','Porque era una colonia de Atenas'],ko:'No: Panticapeo, capital del reino del Bósforo, enviaba a Atenas una gran parte de su trigo, con exención de impuestos.'}},
  src:{a:['Demóstenes, Contra Leptines 29-40','Demóstenes, Contra Lácrito 10-13 (un contrato de préstamo marítimo)','Estrabón VII 4.4-6','Isócrates, Trapecítico 3-5'],m:['V. Gabrielsen y J. Lund (eds.), The Black Sea in Antiquity (2007)'],n:['Estratocles es inventado.','La cifra de 400.000 medimnos es de Demóstenes, a mediados de siglo; los historiadores la discuten.','El «año pasado» (387) Antálcidas cerró el Helesponto con su flota y Atenas tuvo que aceptar la paz.']}},

 {id:'sinope',pos:[35.15,42.03],port:[0,1,'Sinope'],
  isl:{name:'Sinope',gr:'ΣΙΝΩΠΗ · ΠΟΝΤΟΣ'},
  cfg:{site:[60,-130,24],houses:32,spread:110,temple:{name:'Templo de Apolo',W:11,L:20,nW:6,nL:11}},
  steles:[['sinope_colonia','La madre de colonias','ΣΙΝΩΠΗ','Sinope, colonia de Mileto en una península de la costa sur del mar Negro, es a su vez madre de colonias: Trapezunte, Cotiora y Cerasunte las fundaron sinopenses. Tiene dos puertos, uno a cada lado del istmo, y desde aquí se cruza el Ponto por lo más estrecho hasta Crimea. De aquí sale la tierra roja, la «sinópide», que usan los pintores de toda Grecia.'],
   ['sinope_diogenes','El hijo del banquero','ΔΙΟΓΕΝΗΣ','En Sinope vive, o vivía hasta hace poco, un hombre de unos veinticinco años llamado Diógenes, hijo del cambista Hicesias. Se cuenta que padre e hijo falsificaron la moneda de la ciudad y que Diógenes tuvo que irse al destierro. Llegará a Atenas, vivirá en una tinaja, se burlará de Platón y se le llamará «el perro»: el cínico.']],
  vida:{kinds:['olive','plane','pine','cypress'],fauna:[['dog',3],['hen',3],['goat',2]],barks:['El atún pasa por delante en otoño: aquí lo pescamos joven.','La tierra roja de Sinope pinta los barcos y los vasos de media Grecia.','¿Diógenes? Ese loco. Ojalá no vuelva.']},
  npc:{id:'hicesias_sinope',name:'Mnesíteo',title:'Cambista del puerto',glyph:'Μ',look:{chiton:'#e9dfcb',himation:'#7a5a2a',hair:'#6a6a6a',beard:true},
   cat:'Economía',lesson:'Sinope y las colonias del mar Negro',where:'En Sinope, en el Ponto',
   summary:'Sinope, colonia de Mileto en la costa sur del mar Negro, fundó a su vez Trapezunte, Cotiora y Cerasunte. Exportaba atún y la «tierra de Sinope» (ocre rojo). Allí nació hacia el 412 Diógenes, hijo del cambista Hicesias; según Diógenes Laercio, tuvo que exiliarse por falsificar moneda y acabó en Atenas, donde fundó el cinismo.',
   intro:'¿Cambiar? Te doy moneda de Sinope por tus lechuzas atenienses, a buen precio. Y es buena, ¿eh?, no como la de algunos que yo me sé. Soy Mnesíteo.',
   topics:[['¿Qué pasó con la moneda?','Hace poco se descubrió que en el banco de Hicesias se estropeaban monedas: se las rayaba o se les recortaba el borde para sacar plata. Hicesias acabó en la cárcel, y su hijo Diógenes se fue de la ciudad. Dicen que fue a Delfos y que el oráculo le dijo: «Altera la moneda». Él lo entendió a su manera: cambiar los valores de la gente.'],
    ['¿De qué vivís en Sinope?','Del atún, que pasa en otoño camino del Bósforo; del ocre rojo de las minas de Capadocia, que embarcamos aquí; de la madera de los montes; y de ser el puerto donde paran todos los que van de un lado a otro del Ponto. Una buena península con dos puertos vale más que una mina de oro.']],
   quiz:{q:'¿Qué filósofo nació en Sinope?',a:['Diógenes el cínico','Pitágoras','Aristóteles'],ko:'No: en Sinope nació Diógenes, que se exilió y fundó en Atenas el cinismo.'}},
  src:{a:['Diógenes Laercio VI 20-21','Jenofonte, Anábasis V 5.10 y VI 1.15','Estrabón XII 3.11','Teofrasto, Sobre las piedras 52'],m:[],n:['Mnesíteo es inventado.','La fecha del destierro de Diógenes es dudosa; es posible que en el 386 estuviera ya en Atenas.']}},
 {id:'crotona',pos:[17.12,39.08],port:[1,0,'Crotona'],
  isl:{name:'Crotona',gr:'ΚΡΟΤΩΝ · ΙΤΑΛΙΑ'},
  cfg:{site:[90,-130,26],houses:40,spread:120,temple:{name:'Templo de Hera Lacinia',W:14,L:28,nW:6,nL:14}},
  steles:[['crotona_atletas','La ciudad de los atletas','ΜΙΛΩΝ','«El último de los crotoniatas es el primero de los demás griegos», decía un refrán. En una misma carrera de Olimpia, los siete primeros fueron de Crotona. De aquí era Milón, seis veces campeón olímpico de lucha, que de joven cargaba cada día con un ternero hasta que se hizo toro. Y de aquí eran también grandes médicos, como Democedes, que curó al rey Darío, y Alcmeón, que dijo que el cerebro es la sede del pensamiento.'],
   ['crotona_hera','Hera Lacinia','ΛΑΚΙΝΙΟΝ','En el cabo Lacinio, a unos kilómetros de la ciudad, está el gran santuario de Hera, al que acuden todos los griegos de Italia. Se cuenta que el pintor Zeuxis, para pintar a Helena para este templo, eligió a las cinco muchachas más hermosas de Crotona y tomó lo mejor de cada una, porque ninguna era perfecta.']],
  vida:{kinds:['olive','cypress','pine','olive'],fauna:[['dog',2],['hen',4],['goat',3],['pig',2]],barks:['En el gimnasio todavía se cuenta que Milón llevó a hombros un buey entero por el estadio.','Los viejos no comen habas. Dicen que es cosa de Pitágoras.','Dicen que el tirano de Siracusa mira hacia aquí. Que los dioses nos guarden.']},
  npc:{id:'glaucias_crotona',name:'Glaucias',title:'Entrenador de atletas',glyph:'Γ',look:{chiton:'#d8c9a8',exomis:true,hair:'#3a2a1e',beard:true},
   cat:'Historia',lesson:'Crotona: atletas, médicos y pitagóricos',where:'En Crotona, en la Magna Grecia',
   summary:'Crotona, colonia aquea del sur de Italia fundada hacia el 710, fue famosa por sus atletas (Milón, seis veces vencedor olímpico), su escuela médica (Democedes, Alcmeón) y, sobre todo, por Pitágoras, que fundó allí hacia el 530 una comunidad filosófica y religiosa. Hacia mediados del siglo V los pitagóricos fueron atacados y su lugar de reunión, la casa de Milón, incendiado. En el 379 Dionisio I de Siracusa tomará la ciudad.',
   intro:'¡Eh, tú! Tienes piernas de corredor. ¿No? Lástima. Soy Glaucias. En Crotona todo el mundo es atleta, médico o pitagórico. Yo soy lo primero, que es lo más sano.',
   topics:[['¿Por qué ganan tanto los de Crotona?','Por la dieta, el ejercicio y el clima, dicen los médicos. Y por la costumbre: aquí un niño que no corre es como un pájaro que no vuela. Milón comía veinte libras de carne al día y entrenaba cargando un ternero. Yo no llego a tanto, pero mis chicos corren.'],
    ['¿Qué pasó con los pitagóricos?','Llegaron a mandar en la ciudad, con sus juramentos y sus secretos. A la gente no le gustaba que unos pocos se creyeran mejores. Un tal Cilón, al que no quisieron admitir, levantó a la gente, y quemaron la casa de Milón con ellos dentro. De eso hace sesenta años. Quedan algunos viejos que no comen habas y no dicen nada. Y, por la noche, dicen que en las ruinas se ve algo blanco.']],
   quiz:{q:'¿Quién fundó en Crotona una comunidad filosófica y religiosa?',a:['Pitágoras de Samos','Sócrates de Atenas','Arquitas de Tarento'],ko:'No: fue Pitágoras de Samos, que llegó a Crotona hacia el 530 a.C.'}},
  src:{a:['Estrabón VI 1.12','Diógenes Laercio VIII 1-50','Jámblico, Vida pitagórica 248-262','Cicerón, De inventione II 1-3 (Zeuxis)'],m:['W. Burkert, Lore and Science in Ancient Pythagoreanism (1972)'],n:['Glaucias es inventado.']}}
];
