// ============================================================ SUELO: las personas, sobre el suelo que se ve
// El suelo físico (terrainH, con los allanamientos exactos junto a los edificios) y la malla que se dibuja (un vértice cada ~5 m)
// no coinciden del todo: junto a un templo o en una pendiente, alguien colocado en el suelo físico puede flotar o hundirse en lo que se ve.
// Justo antes de dibujar cada imagen, las personas cercanas que están en el suelo se recolocan a la altura de lo que se ve:
// sobre la malla del terreno, o sobre el suelo de un edificio (plataformas) si están encima de uno.
// No se tocan: las que cuelgan de otro objeto (talleres, carros, barcos), las estatuas y las que están a otra altura a propósito.
const PEOPLE=[],SUELO={on:true,R:90,fix:0,meshes:null};
{const mp0=makePerson;makePerson=function(c){const g=mp0(c);PEOPLE.push(g);return g;};}
function sueloMeshes(){const L=[];const add=(m,I)=>{if(!m||!m.geometry||!m.geometry.parameters)return;const P=m.geometry.parameters,pos=m.geometry.attributes.position;L.push({m,I,pos,n:P.widthSegments,x0:pos.getX(0),z0:pos.getZ(0),st:P.width/P.widthSegments});};
  add(terrainInner,null);for(const I of ISLANDS)if(I&&I.mesh)add(I.mesh,I);return L;}
function meshH(x,z){if(!SUELO.meshes||!SUELO.meshes.length)SUELO.meshes=sueloMeshes();
  for(const g of SUELO.meshes){if(g.I?Math.abs(x-g.I.x)>g.I.R*1.5:x>8000)continue;const u=(x-g.x0)/g.st,w=(z-g.z0)/g.st;if(u<0||w<0||u>=g.n||w>=g.n)continue;
    const ix=Math.floor(u),iy=Math.floor(w),fu=u-ix,fv=w-iy,N=g.n+1,Y=i=>g.pos.getY(i),a=Y(iy*N+ix),b=Y((iy+1)*N+ix),c=Y((iy+1)*N+ix+1),d=Y(iy*N+ix+1);
    return fu+fv<=1?a+(d-a)*fu+(b-a)*fv:c+(b-c)*(1-fu)+(d-c)*(1-fv);}
  return null;}
// la altura a la que debe estar alguien que pisa el suelo en (x,z)
function groundY(x,z){const f=floorAt(x,z),t=terrainH(x,z);if(f>t+0.05)return f;const m=meshH(x,z);return m===null?f:m;}
function sueloTick(){if(!SUELO.on||!state||typeof player==='undefined')return;const R2=SUELO.R*SUELO.R;
  for(let i=PEOPLE.length-1;i>=0;i--){const g=PEOPLE[i];if(!g.parent){if(g.userData.gone>200)PEOPLE.splice(i,1);else g.userData.gone=(g.userData.gone||0)+1;continue;}g.userData.gone=0;
    if(g.parent!==scene||!g.visible||g.userData.noSnap)continue;const p=g.position,dx=p.x-player.x,dz=p.z-player.z;if(dx*dx+dz*dz>R2)continue;
    const f=floorAt(p.x,p.z),y=groundY(p.x,p.z);
    if(p.y<y-0.03&&p.y>y-1.2){p.y=y;SUELO.fix++;continue;}   // nadie por debajo del suelo que se ve
    if(Math.abs(p.y-f)>0.2)continue;   // por encima, solo se baja a quien está puesto en el suelo físico: no a las estatuas ni a quien está a otra altura a propósito
if(Math.abs(y-p.y)>0.03&&Math.abs(y-p.y)<2.5){p.y=y;SUELO.fix++;}}}
scene.onBeforeRender=function(){try{sueloTick();}catch(e){}};
